// Any failed run of the other workflows lands here, so failures are never silent:
// it is logged and recorded in Convex (visible to admins).
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const PATH = '/n8n/events';
const { execution = {}, workflow = {} } = $input.first().json;
const message = (execution.error && execution.error.message) || 'unknown error';
const detail = `${workflow.name || 'workflow'} failed at "${execution.lastNodeExecuted || '?'}": ${message}`.slice(0, 300);
console.error('[LendLoop automation error]', detail);
const body = JSON.stringify({ eventKey: `workflow_error:${workflow.id}:${execution.id}`, kind: 'workflow_error', detail });
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.POST.${PATH}.${body}`).digest('hex');
return [{ json: { body, ts, sig } }];
